import java.util.*;class Solution{public boolean wordPattern(String p,String s){String[]w=s.split(" ");if(p.length()!=w.length)return false;Map<Character,String>a=new HashMap<>();Map<String,Character>b=new HashMap<>();for(int i=0;i<w.length;i++){char c=p.charAt(i);if(a.containsKey(c)&&!a.get(c).equals(w[i])||b.containsKey(w[i])&&b.get(w[i])!=c)return false;a.put(c,w[i]);b.put(w[i],c);}return true;}}
